import{_ as p,a0 as n,w as o,s as d,ao as h,I as l,x as i,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"15 个可以节省你时间的命令别名 | LCTT x X-CMD","titleTemplate":false,"description":"15 个可以节省你时间的命令别名 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"15 个可以节省你时间的命令别名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"15 个可以节省你时间的命令别名 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180828 15 command-line aliases to save you time","title":"15 个可以节省你时间的命令别名","tag":"201809","desc":""},"relativePath":"201809/20180828 15 command-line aliases to save you time.md","filePath":"[post].md"}'),r={name:"201809/20180828 15 command-line aliases to save you time.md"};function u(g,s,k,c,b,m){const e=n("Link");return o(),d("div",null,[s[15]||(s[15]=h('<h1 id="_15-个可以节省你时间的命令别名" tabindex="-1">15 个可以节省你时间的命令别名 <a class="header-anchor" href="#_15-个可以节省你时间的命令别名" aria-label="Permalink to “15 个可以节省你时间的命令别名”">​</a></h1><blockquote><p>在你安装的 Linux 发行版中默认就包含了一些别名。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/computer_keyboard_laptop_development_blue.png?itok=IfckxN48" alt=""></p><p>Linux 命令行别名非常适合帮助你提高工作效率。更好的是，在你安装的 Linux 发行版中默认就包含了一些别名。</p><p>这是 Fedora 27 中的命令别名的示例：</p><p><img src="https://opensource.com/sites/default/files/uploads/default.png" alt=""></p><p>这个 <code>alias</code> 命令列出了已有的别名。设置别名也十分简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias new_name=&quot;command&quot;</span></span></code></pre></div><p>这里有 15 个命令行别名，可以节省你的时间：</p><p>1、安装任何应用实用 / 应用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias install=&quot;sudo yum install -y&quot;</span></span></code></pre></div><p>在这里，根据每个用户的偏好，<code>sudo</code> 和 <code>-y</code> 是可选的：</p><p><img src="https://opensource.com/sites/default/files/uploads/install.png" alt="install alias.png" title="install alias.png"></p><p>2、更新系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias update=&quot;sudo yum update -y&quot;</span></span></code></pre></div><p>3、升级系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias upgrade=&quot;sudo yum upgrade -y&quot;</span></span></code></pre></div><p>4、切换 root 用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias root=&quot;sudo su -&quot;</span></span></code></pre></div><p>5、切换到 “user” 用户, 其中 <code>user</code> 设置为你的用户名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias user=&quot;su user&quot;</span></span></code></pre></div><p>6、显示列出所有可用端口、状态还有 IP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias myip=&quot;ip -br -c a&quot;</span></span></code></pre></div><p>7、<code>ssh</code> 到你的服务器 <code>myserver</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias myserver=&quot;ssh user@my_server_ip”</span></span></code></pre></div><p>8、列出系统中所有进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias process=&quot;ps -aux&quot;</span></span></code></pre></div><p>9、检查系统的服务状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias sstatus=&quot;sudo systemctl status&quot;</span></span></code></pre></div><p>10、重启系统服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias srestart=&quot;sudo systemctl restart&quot;</span></span></code></pre></div><p>11、按名称杀死进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias kill=&quot;sudo pkill&quot;</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/kill.png" alt="kill process alias.png" title="kill process alias.png"></p><p>12、显示系统系统总使用内存和空闲内存 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias mem=&quot;free -h&quot;</span></span></code></pre></div><p>13、显示系统 CPU 框架结构、CPU 数量、线程数等：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cpu=&quot;lscpu&quot;</span></span></code></pre></div><p>14、显示系统总磁盘大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias disk=&quot;df -h&quot;</span></span></code></pre></div><p>15、显示当前系统 Linux 发行版本（适用于 CentOS、Fedora 和 Red Hat)：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias os=&quot;cat /etc/redhat-release&quot;</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/system_details.png" alt="system_details alias.png" title="system_details alias.png"></p><hr>',44)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://opensource.com/article/18/8/time-saving-command-line-aliases"},{default:a(()=>[...s[0]||(s[0]=[i("https://opensource.com/article/18/8/time-saving-command-line-aliases",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://opensource.com/users/architmodi"},{default:a(()=>[...s[2]||(s[2]=[i("Aarchit Modi",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),t(e,{href:"https://github.com/MZqk"},{default:a(()=>[...s[4]||(s[4]=[i("MZqk",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[11]||(s[11]=[i("Linux 中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const v=p(r,[["render",u]]);export{C as __pageData,v as default};
